"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["66865"],{64523(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.retificacao.fato_ausente_de_versao_publicada","status":422,"titulo":"Fato de outra finalidade n\xe3o coletado em todas as vers\xf5es publicadas"},"descricao":{"codigo":"uniplus.selecao.retificacao.fato_ausente_de_versao_publicada","requisitos":["UNI-REQ-0144"],"oQueAconteceu":["Cada processo tem um formul\xe1rio por finalidade (inscri\xe7\xe3o, isen\xe7\xe3o da taxa, habilita\xe7\xe3o), e o candidato pode ter preenchido o formul\xe1rio de uma finalidade em qualquer vers\xe3o publicada do edital (o primeiro envio fixa a vers\xe3o). Por isso, quem preencheu o formul\xe1rio de uma finalidade numa vers\xe3o anterior pode n\xe3o ter informado um fato que s\xf3 foi acrescentado depois.","Na retifica\xe7\xe3o em ato \xfanico, a vers\xe3o nova leva a configura\xe7\xe3o que o processo j\xe1 tem. Se essa configura\xe7\xe3o cita, num formul\xe1rio, num termo ou numa condi\xe7\xe3o de documento exigido, um fato coletado pelo formul\xe1rio de **outra finalidade**, e esse formul\xe1rio n\xe3o coletou o fato em **todas** as vers\xf5es j\xe1 publicadas do edital, a retifica\xe7\xe3o \xe9 recusada: basta faltar em uma delas. A confer\xeancia \xe9 por finalidade: o formul\xe1rio que cita os pr\xf3prios fatos segue a vers\xe3o dele mesmo e n\xe3o \xe9 recusado por esta causa. Tamb\xe9m vale para o fato derivado: se ele depende de um fato coletado nessas condi\xe7\xf5es, a recusa \xe9 a mesma. A finalidade que ainda n\xe3o tinha formul\xe1rio em nenhuma vers\xe3o publicada n\xe3o \xe9 recusada, porque ningu\xe9m o preencheu antes.","A recusa sai com **422**, e o `detail` diz o fato, quem o cita e a finalidade do formul\xe1rio que deveria t\xea-lo coletado. Quando a cita\xe7\xe3o \xe9 a um fato derivado, o `detail` diz tamb\xe9m de qual fato coletado ele depende. A confer\xeancia s\xf3 existe na retifica\xe7\xe3o: sem vers\xe3o publicada nenhum candidato preencheu vers\xe3o anterior, e a recusa n\xe3o ocorre. Ela \xe9 feita ao congelar a vers\xe3o nova e alcan\xe7a tamb\xe9m o fato derivado cuja regra de deriva\xe7\xe3o, em vigor no cadastro de fatos, depende de um fato coletado nessas condi\xe7\xf5es.","O motivo \xe9 de neg\xf3cio: o candidato pode ter preenchido o formul\xe1rio de origem em qualquer vers\xe3o publicada (UNI-REQ-0144). Exemplo hipot\xe9tico, porque o pedido de retifica\xe7\xe3o em ato \xfanico ainda n\xe3o altera formul\xe1rios: o formul\xe1rio de inscri\xe7\xe3o passa a perguntar a \\"Escola de conclus\xe3o do ensino m\xe9dio\\" s\xf3 depois de uma vers\xe3o posterior, e o formul\xe1rio de habilita\xe7\xe3o cita essa resposta. Quem se inscreveu antes nunca a informou, e a habilita\xe7\xe3o dele n\xe3o teria o dado.","Esta regra vale para o modelo atual, de um formul\xe1rio por finalidade. Quando o formul\xe1rio passar a ser identificado por c\xf3digo, e n\xe3o por finalidade, ela muda."],"comoResolver":["O pedido de retifica\xe7\xe3o em ato \xfanico n\xe3o traz formul\xe1rio, termo nem exig\xeancia de documento, ent\xe3o n\xe3o h\xe1 o que ajustar nele. Esses itens v\xeam da configura\xe7\xe3o que o processo j\xe1 tem, e a retifica\xe7\xe3o n\xe3o os altera.","Se a recusa aparecer, a causa est\xe1 na configura\xe7\xe3o do processo ou na regra de deriva\xe7\xe3o do cadastro de fatos, e n\xe3o no pedido enviado. Procure a equipe t\xe9cnica do Uni+ e, se a causa for a regra de deriva\xe7\xe3o, quem administra o cadastro de fatos."],"ondeAparece":["Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Retificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);